    if (!Number.isFinite(value) || (type === 'bet' ? value <= 0 : value < 0)) {
      return { status: 400, body: { error: { code: 'INVALID_AMOUNT', message: 'Некорректная сумма' } } };
    }

    const requested = amount as number;
    const prev = state.transactions[txId];
    if (prev) {
      // Сравнивается сумма из запроса до округления: 2.5 и 2.504 — разные данные (у старых записей — округлённая).
      const prevRequested = prev.requestedAmount ?? prev.amount;
      if (prev.type === type && prev.roundId === roundId && prevRequested === requested) return { status: prev.status, body: prev.body };
      return { status: 409, body: { error: { code: 'TX_CONFLICT', message: 'txId уже использован с другими данными' } } };
    }

    let balance = state.balance;
    let result: { status: number; body: unknown };
    if (type === 'bet' && value > balance) {
      result = { status: 402, body: { error: { code: 'INSUFFICIENT_FUNDS', message: 'Недостаточно средств' }, balance } };
    } else {
      balance = round2(type === 'bet' ? balance - value : balance + value);
      result = { status: 200, body: { balance } };
    }
    const tx: WalletTx = { type, roundId, amount: value, requestedAmount: requested, status: result.status, body: result.body };
    // Сначала диск, потом память: если запись упадёт, баланс и журнал в памяти останутся прежними.
    persist({ ...state, balance, transactions: { ...state.transactions, [txId]: tx } });
    state.balance = balance;
    state.transactions[txId] = tx;
    return result;
  };

  const server = http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url ?? '/', 'http://wallet');
      if (req.method === 'GET' && url.pathname === '/balance') return sendJson(res, 200, { balance: state.balance });
      if (req.method === 'POST' && (url.pathname === '/bet' || url.pathname === '/payout')) {
        const body = await readJson(req);
        const r = transact(url.pathname === '/bet' ? 'bet' : 'payout', body);
        return sendJson(res, r.status, r.body);
      }
      throw new PlatformError('NOT_FOUND');
    } catch (e) {
      sendError(res, e);
    }
  });

  return listen(server, opts.port, opts.host ?? '127.0.0.1');
}

function loadState(file: string): WalletState {
  if (!fs.existsSync(file)) return { player: PLAYER_ID, balance: START_BALANCE, transactions: {} };
  // Битый файл — ошибка запуска: молча сбросить баланс игрока нельзя.
  const data = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<WalletState>;
  if (typeof data.balance !== 'number' || !Number.isFinite(data.balance)) throw new Error(`${file}: некорректный баланс`);
  return { player: PLAYER_ID, balance: data.balance, transactions: data.transactions ?? {} };
}
/**
 * Ядро платформы — HTTP-сервис: API раундов, оболочка `/`, интерфейсы игр `/games/<id>/` и SDK `/sdk.js`.
 * Раунды хранятся в `<dataDir>/rounds.json`, деньги проводятся через кошелёк по `walletUrl`.
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Rng } from '../sdk/types.ts';
import { PlatformError } from '../shared/errors.ts';
import { listen, readJson, sendError, sendJson, type RunningServer } from '../shared/http.ts';
import { RoundEngine, runAsync, type EngineGen } from './engine.ts';
import { loadGames, type LoadedGame } from './games.ts';
import { FileRoundStore } from './store.ts';
import { walletExecutor } from './wallet-client.ts';

export type { RunningServer };

const here = path.dirname(fileURLToPath(import.meta.url));
const SDK_FILE = path.join(here, '..', 'sdk', 'client.js');
const SHELL_FILE = path.join(here, 'shell.html');

const CONTENT_TYPES: Readonly<Record<string, string>> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
};

/** Настройки запуска ядра. */
export interface CoreOptions {
  /** Порт; 0 — свободный. */
  port: number;
  /** Каталог данных, где лежит `rounds.json`. */
  dataDir: string;
  /** Каталог игр, где ищутся `*\/manifest.json`. */
  gamesDir: string;
  /** Адрес кошелька, например `http://127.0.0.1:4001`. */
  walletUrl: string;
  /** Адрес прослушивания; по умолчанию `127.0.0.1`. */
  host?: string;
  /** Генератор случайных чисел; по умолчанию криптостойкий `cryptoRng`. */
  rng?: Rng;
}

/** Криптостойкий генератор на `node:crypto`: равномерное число в [0, 1) с шагом 2⁻⁴⁸. */
export const cryptoRng: Rng = {
  next: () => crypto.randomBytes(6).readUIntBE(0, 6) / 2 ** 48,
};

/** Запускает ядро: загружает игры и раунды, поднимает HTTP-сервис. */
export async function startCore(opts: CoreOptions): Promise<RunningServer> {
  const games = await loadGames(opts.gamesDir);
  const byId = new Map<string, LoadedGame>(games.map((g) => [g.manifest.id, g]));
  const engine = new RoundEngine({
    games: games.map((g) => g.module),
    store: new FileRoundStore(path.join(opts.dataDir, 'rounds.json')),
    rng: opts.rng ?? cryptoRng,
    newRoundId: () => crypto.randomUUID(),
  });
  const exec = walletExecutor(opts.walletUrl);

  // Операции движка выполняются строго по очереди: проверка «нет открытого раунда» и списание атомарны.
  let queue: Promise<unknown> = Promise.resolve();
  const run = <T>(gen: () => EngineGen<T>): Promise<T> => {
    const p = queue.then(() => runAsync(gen(), exec));
    queue = p.catch(() => undefined);
    return p;
  };

  const handleApi = async (req: http.IncomingMessage, res: http.ServerResponse, parts: string[]): Promise<void> => {
    const method = req.method ?? 'GET';
    // GET /api/games
    if (parts.length === 1 && parts[0] === 'games' && method === 'GET') {
      return sendJson(res, 200, games.map((g) => ({ id: g.manifest.id, title: g.manifest.title })));
    }
    // GET /api/balance — для оболочки
    if (parts.length === 1 && parts[0] === 'balance' && method === 'GET') {
      return sendJson(res, 200, { balance: await exec({ kind: 'balance' }) });
    }
    if (method === 'POST' && parts.length === 3) {
      checkSameOrigin(req);
      const [kind, id, verb] = parts as [string, string, string];
      if (kind === 'games' && verb === 'open') {
        await readJson(req);
        return sendJson(res, 200, await run(() => engine.open(id)));
      }
      if (kind === 'games' && verb === 'rounds') {
        const body = ((await readJson(req)) ?? {}) as { bet?: unknown; params?: unknown };
        return sendJson(res, 200, await run(() => engine.startRound(id, body.bet, body.params)));
      }
      if (kind === 'rounds' && verb === 'actions') {
        const body = ((await readJson(req)) ?? {}) as { action?: unknown };
        return sendJson(res, 200, await run(() => engine.action(id, body.action)));
      }
    }
    throw new PlatformError('NOT_FOUND');
  };

  const server = http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url ?? '/', 'http://core');
      const parts = url.pathname.split('/').filter(Boolean).map((p) => decodeURIComponent(p));
      if (parts[0] === 'api') return await handleApi(req, res, parts.slice(1));
      if (req.method !== 'GET' && req.method !== 'HEAD') throw new PlatformError('NOT_FOUND');
      if (url.pathname === '/' || url.pathname === '/index.html') return sendFile(req, res, SHELL_FILE);
      if (url.pathname === '/sdk.js') return sendFile(req, res, SDK_FILE);
      if (parts[0] === 'games' && parts[1]) {
        const game = byId.get(parts[1]);
        if (!game) throw new PlatformError('GAME_NOT_FOUND');
        if (parts.length === 2 && !url.pathname.endsWith('/')) {
          res.writeHead(301, { location: `/games/${encodeURIComponent(parts[1])}/` });
          return void res.end();
        }
        const uiDir = path.dirname(game.uiFile);
        const rest = parts.slice(2);
        const file = rest.length === 0 ? game.uiFile : path.resolve(uiDir, ...rest);
        if (file !== game.uiFile && !file.startsWith(uiDir + path.sep)) throw new PlatformError('NOT_FOUND');
        return sendFile(req, res, file);
      }
      throw new PlatformError('NOT_FOUND');
    } catch (e) {
      if (e instanceof URIError) return sendError(res, new PlatformError('INVALID_REQUEST'));
      sendError(res, e);
    }
  });

  return listen(server, opts.port, opts.host ?? '127.0.0.1');
}

/**
 * Защита API от запросов со сторонних сайтов (CSRF): заголовок `Origin`, если он есть, должен совпадать с `Host`,
 * а непустое тело — иметь тип `application/json` (такой запрос браузер не отправит с чужого сайта без preflight).
 */
function checkSameOrigin(req: http.IncomingMessage): void {
  const origin = req.headers.origin;
  if (origin !== undefined) {
    let host: string | undefined;
    try {
      host = new URL(origin).host;
    } catch {
      host = undefined;
    }
    if (!host || host !== req.headers.host) throw new PlatformError('FORBIDDEN');
  }
  const length = Number(req.headers['content-length'] ?? 0);
  const hasBody = req.headers['transfer-encoding'] !== undefined || length > 0;
  const type = String(req.headers['content-type'] ?? '').split(';')[0]?.trim().toLowerCase();
  if (hasBody && type !== 'application/json') throw new PlatformError('UNSUPPORTED_MEDIA_TYPE');
}

function sendFile(req: http.IncomingMessage, res: http.ServerResponse, file: string): void {
  let data: Buffer;
  try {
    if (!fs.statSync(file).isFile()) throw new Error('not a file');
    data = fs.readFileSync(file);
  } catch {
    throw new PlatformError('NOT_FOUND');
  }
  const type = CONTENT_TYPES[path.extname(file).toLowerCase()] ?? 'application/octet-stream';
  res.writeHead(200, { 'content-type': type, 'content-length': data.length, 'cache-control': 'no-cache' });
  res.end(req.method === 'HEAD' ? undefined : data);
}
/** Клиент кошелька для ядра: выполняет операции движка (`WalletOp`) по HTTP через `node:http`. */
import http from 'node:http';
import { PlatformError, messageOf } from '../shared/errors.ts';
import type { WalletOp } from './engine.ts';

const TIMEOUT_MS = 5000;

/**
 * Создаёт исполнитель операций кошелька по адресу `walletUrl`.
 * `402` → `INSUFFICIENT_FUNDS`; сеть, таймаут, `5xx` → `WALLET_UNAVAILABLE`; прочие отказы → `INTERNAL_ERROR`.
 */
export function walletExecutor(walletUrl: string): (op: WalletOp) => Promise<number> {
  return async (op) => {
    const res =
      op.kind === 'balance'
        ? await call(walletUrl, 'GET', '/balance')
        : await call(walletUrl, 'POST', `/${op.kind}`, { txId: op.txId, roundId: op.roundId, amount: op.amount });
    const body = res.body as { balance?: unknown; error?: { code?: unknown } } | undefined;
    if (res.status === 200 && typeof body?.balance === 'number') return body.balance;
    if (res.status === 402) throw new PlatformError('INSUFFICIENT_FUNDS');
    if (res.status >= 500 || res.status === 200) throw new PlatformError('WALLET_UNAVAILABLE');
    throw new PlatformError('INTERNAL_ERROR', `Кошелёк отклонил операцию: ${String(body?.error?.code ?? res.status)}`);
  };
}

function call(base: string, method: string, urlPath: string, body?: unknown): Promise<{ status: number; body: unknown }> {
  const payload = body === undefined ? undefined : JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const fail = (e: unknown): void => reject(new PlatformError('WALLET_UNAVAILABLE', `Кошелёк недоступен: ${messageOf(e)}`));
    const req = http.request(
      new URL(urlPath, base),
      {
        method,
        timeout: TIMEOUT_MS,
        headers: payload === undefined ? {} : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (c: Buffer) => chunks.push(c));
        res.on('error', fail);
        res.on('end', () => {
          let parsed: unknown;
          try {
            parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
          } catch {
            parsed = undefined;
          }
          resolve({ status: res.statusCode ?? 0, body: parsed });
        });
      },
    );
    req.on('timeout', () => req.destroy(new Error('timeout')));
    req.on('error', fail);
    if (payload !== undefined) req.write(payload);
    req.end();
  });
}
/**
 * Запуск приложения: `pnpm start` поднимает кошелёк (4001) и ядро (4000).
 * Данные — в `data/`, игры — в `games/` (относительно корня репозитория).
 */
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { startCore } from './core/index.ts';
import { startWallet } from './wallet/index.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dataDir = path.join(root, 'data');
const gamesDir = path.join(root, 'games');

const wallet = await startWallet({ port: 4001, dataDir });
const core = await startCore({ port: 4000, dataDir, gamesDir, walletUrl: wallet.url });

console.log(`Кошелёк: ${wallet.url}`);
console.log(`Приложение: http://localhost:4000 (${core.url})`);

const stop = async (): Promise<void> => {
  await core.close();
  await wallet.close();
  process.exit(0);
};
process.once('SIGINT', stop);
process.once('SIGTERM', stop);
/** Мелкие помощники для HTTP-сервисов на `node:http`. */
import http from 'node:http';
import { PlatformError } from './errors.ts';

/** Запущенный HTTP-сервис. */
export interface RunningServer {
  /** Фактический адрес, например `http://127.0.0.1:4000`. */
  url: string;
  /** Останавливает сервис и закрывает соединения. */
  close(): Promise<void>;
}

const MAX_BODY = 1024 * 1024;

/** Читает JSON-тело запроса. Пустое тело — `undefined`, битый JSON — `PlatformError('INVALID_REQUEST')`. */
export async function readJson(req: http.IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY) throw new PlatformError('INVALID_REQUEST', 'Слишком большое тело запроса');
    chunks.push(chunk as Buffer);
  }
  const text = Buffer.concat(chunks).toString('utf8').trim();
  if (!text) return undefined;
  try {
    return JSON.parse(text);
  } catch {
    throw new PlatformError('INVALID_REQUEST', 'Тело запроса — не JSON');
  }
}

/** Отправляет JSON-ответ. */
export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(text), 'cache-control': 'no-store' });
  res.end(text);
}

/** Отправляет ошибку в формате `{ error: { code, message } }`; неизвестная ошибка — 500 `INTERNAL_ERROR`. */
export function sendError(res: http.ServerResponse, e: unknown, extra: Record<string, unknown> = {}): void {
  const err = e instanceof PlatformError ? e : new PlatformError('INTERNAL_ERROR');
  if (!(e instanceof PlatformError)) console.error(e);
  else if (err.detail !== undefined) console.error(`${err.code}: ${err.detail}`);
  sendJson(res, err.status, { error: { code: err.code, message: err.message }, ...extra });
}

/** Запускает сервер на `host:port` (`port: 0` — свободный порт) и возвращает `RunningServer`. */
export function listen(server: http.Server, port: number, host: string): Promise<RunningServer> {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      const addr = server.address();
      const actual = typeof addr === 'object' && addr ? addr.port : port;
      const urlHost = host.includes(':') ? `[${host}]` : host;
      resolve({
        url: `http://${urlHost}:${actual}`,
        close: () =>
          new Promise<void>((done) => {
            server.close(() => done());
            server.closeAllConnections();
          }),
      });
    });
  });
}

