function req(base: string, method: string, p: string, headers: Record<string, string>, body?: string): Promise<number> {
  return new Promise((ok, fail) => {
    const r = http.request(new URL(p, base), { method, headers }, (res) => { res.resume(); res.on('end', () => ok(res.statusCode ?? 0)); });
